请对以下 case 进行三维加权评分。

=== case_id ===
Case-25-reading-481

=== 用户原始指令 (query.txt) ===
弄个有图的阅读进度卡，点一下能跳

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个有图的阅读进度卡，点一下能跳",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModel": {
    "value": {
      "reading": {
        "title": "阅读进度",
        "book": "听书计划",
        "progressText": "已读 68%",
        "percent": 68,
        "total": 100,
        "coverIcon": "resources/base/media/icon_music.png",
        "actionLabel": "继续听"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "reading_audio_icon",
      "src": "resources/base/media/icon_music.png",
      "use": "audio reading illustration",
      "description": "音乐图标素材，用于表达听书或音频阅读的入口视觉。",
      "bindTo": "/reading/coverIcon",
      "static": true
    }
  ]
}

